using System;using System.IO;using System.Linq;using System.Reflection;using System.Threading.Tasks;using UnityEngine;using UnityEditor;using AntColony.Units;using AntColony.Buildings;using AntColony.Core;using AntColony.Data;using AntColony.UI;
public static class Final1113BedUse {
 public static async Task<string> Run(){
 if(!Application.isPlaying||UserSettings.Current.autoSaveEnabled||string.IsNullOrEmpty(AntColony.Save.SaveStorage.RootOverride))throw new Exception("isolated play required");
 var actors=CommanderRoster.Instance.Commanders.Where(c=>c&&c.IsColonyMember).ToArray();foreach(var c in actors){c.CommandStop();c.SetJobEnabled(CommanderJobs.All,false);c.GetComponent<MeshyNativeMotionPlayer>().PreviewMotion=null;}
 var research=CampaignResearch.Instance.CaptureState();research.completed.Add((int)ScienceTechnology.Infirmary);CampaignResearch.Instance.RestoreState(research);SimulationPause.UserSpeed(0);
 var home=(Vector3)typeof(ResourceManager).GetProperty("HomePosition",BindingFlags.Static|BindingFlags.NonPublic).GetValue(null);var center=home+new Vector3(0,0,-12);if(Physics.Raycast(center+Vector3.up*50,Vector3.down,out var g,100,1<<8))center.y=g.point.y;
 var template=(GameObject)typeof(BuildingPlacementController).GetMethod("GetTemplate",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{BuildingKind.Infirmary,UnitRole.Worker});var go=UnityEngine.Object.Instantiate(template,center+Vector3.up,Quaternion.identity);go.name="Final treatment beds";go.SetActive(true);var hospital=go.GetComponent<Infirmary>();FacilityVisual.Attach(hospital);await Task.Delay(400);
 for(int i=0;i<2;i++){var c=actors[i];if(UnityEngine.AI.NavMesh.SamplePosition(center+new Vector3(-3,0,i*2),out var hit,3,UnityEngine.AI.NavMesh.AllAreas))c.Agent.Warp(hit.position);c.PersonalState.health=new HealthState{migrated=true,selfTend=false,medicine=MedicineLevel.NoMedicine};c.Health.wounds.Add(new Wound{part=AntColony.Units.BodyPart.ArmL,kind=WoundKind.Cut,damage=15});if(!hospital.TryAdmit(c))throw new Exception("admit "+i+" free="+hospital.HasFreeBed+" allocate="+c.CanChangeAllocation+" working="+c.IsWorking+" needs="+c.PersonalState.NeedsTreatment+" distance="+Vector3.Distance(c.Position,hospital.Position)+" dead="+c.IsDead);}
 SimulationPause.UserSpeed(1);await Task.Delay(800);SimulationPause.UserSpeed(0);
 string result="";for(int i=0;i<2;i++){var c=actors[i];var p=c.GetComponent<MeshyNativeMotionPlayer>();if(p.PlayingMotion!="Sleep_Normally")throw new Exception("patient not asleep "+p.PlayingMotion);hospital.TryRestPose(c,out var pos,out var dir);result+=$"patient{i} motion={p.PlayingMotion} visual={c.GetComponent<AntVisual>().MotionName} rest={pos:F3} headDirection={dir:F3} preview={p.PreviewMotion}\n";}
 if(hospital.HasFreeBed)throw new Exception("capacity violated");
 var camera=Camera.main;UnityEngine.Object.FindAnyObjectByType<AntColony.Camera.IsometricCameraController>().enabled=false;camera.orthographicSize=3.1f;camera.transform.position=center+new Vector3(-4,6,-5);camera.transform.LookAt(center+Vector3.up*.7f);EditorWindow.GetWindow(typeof(Editor).Assembly.GetType("UnityEditor.GameView")).Focus();await Task.Delay(200);ScreenCapture.CaptureScreenshot("work/final-motion-1113/bed-use.png");await Task.Delay(250);File.WriteAllText("work/final-motion-1113/bed-use.txt",result);return result;
 }
}
